import{_ as o,o as a,c as e,ag as r}from"./chunks/framework.B5ULsuav.js";const p=JSON.parse('{"title":"在工作中修行","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-工作修行.md","filePath":"20-专题研究/topic-工作修行.md","lastUpdated":1778155802000}'),d={name:"20-专题研究/topic-工作修行.md"};function i(h,t,l,u,s,n){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="在工作中修行" tabindex="-1">在工作中修行 <a class="header-anchor" href="#在工作中修行" aria-label="Permalink to &quot;在工作中修行&quot;">​</a></h1><blockquote><p>专题分析：工作即道场 组合模型：历境炼心 + 自然务实 + 圆融中和</p></blockquote><hr><h2 id="一、核心理念-工作本身就是修行" tabindex="-1">一、核心理念：工作本身就是修行 <a class="header-anchor" href="#一、核心理念-工作本身就是修行" aria-label="Permalink to &quot;一、核心理念：工作本身就是修行&quot;">​</a></h2><p>了空居士在答疑中反复强调，工作不是修行的障碍，而是最好的修行现场。</p><blockquote><p><strong>&quot;认真工作也是禅定。生活处处是道场，为人处世样样是修行。你等一下工作做完，一盘起腿来一认认真真地念佛，本来心情就平静。一坐下来就深入境界了。一收功又去做事，又是在禅定之中做事。做完事又来练功，又是深入境界了。&quot;</strong></p></blockquote><p>— 修行即生活（20090111b）</p><blockquote><p><strong>&quot;假如工作生活到处都是风风火火，到处都是神不守舍……等下有空一坐下来，怎么坐都静不下去。努力地坐了半个小时、一个小时，马马虎虎能够静下来，一看时间已经过去了……天天如是，这个就是竹篮打水一场空了。&quot;</strong></p></blockquote><p>— 修行即生活（20090111b）</p><hr><h2 id="二、工作中的三个修行维度" tabindex="-1">二、工作中的三个修行维度 <a class="header-anchor" href="#二、工作中的三个修行维度" aria-label="Permalink to &quot;二、工作中的三个修行维度&quot;">​</a></h2><h3 id="_1-在具体事务中历境炼心" tabindex="-1">1. 在具体事务中历境炼心 <a class="header-anchor" href="#_1-在具体事务中历境炼心" aria-label="Permalink to &quot;1. 在具体事务中历境炼心&quot;">​</a></h3><blockquote><p><strong>&quot;把每一天遇到的每一件事都当作修行的机会。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></p><p>工作场景中的具体应用：</p><table tabindex="0"><thead><tr><th>场景</th><th>历境炼什么</th></tr></thead><tbody><tr><td>被领导批评</td><td>不生嗔恚，客观分析有没有道理</td></tr><tr><td>同事抢功</td><td>不生嫉妒，&quot;随喜&quot;他的成就 — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经11分-随喜即众善">金刚经11分-随喜即众善</a></td></tr><tr><td>工作压力大</td><td>问自己&quot;我为什么要焦虑？&quot; — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></td></tr><tr><td>加班累了</td><td>不抱怨，知道这是修行的一部分</td></tr></tbody></table><h3 id="_2-抓核心、做实事" tabindex="-1">2. 抓核心、做实事 <a class="header-anchor" href="#_2-抓核心、做实事" aria-label="Permalink to &quot;2. 抓核心、做实事&quot;">​</a></h3><blockquote><p><strong>&quot;不要长篇大论，抓住核心，在生活中落实。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-抓住核心">金刚经1分-抓住核心</a></p><p>工作中了空居士的方法论就是<strong>化繁为简，直指核心</strong>。</p><blockquote><p><strong>&quot;因上精进，果上随缘就是中观。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/道德经14章-因上精进果上随缘">道德经14章-因上精进果上随缘</a></p><h3 id="_3-用整体观处理工作关系" tabindex="-1">3. 用整体观处理工作关系 <a class="header-anchor" href="#_3-用整体观处理工作关系" aria-label="Permalink to &quot;3. 用整体观处理工作关系&quot;">​</a></h3><blockquote><p><strong>&quot;整体观定善恶——对大众对整体有利的事情就是好事。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/论坛-整体观定善恶">论坛-整体观定善恶</a></p><p>工作中少不了利益冲突。了空居士说：站到整体角度——与合作方有分歧，找共赢方案；被误解，不急于辩解，从对方的立场理解。</p><hr><h2 id="三、了空居士的日常工作开示" tabindex="-1">三、了空居士的日常工作开示 <a class="header-anchor" href="#三、了空居士的日常工作开示" aria-label="Permalink to &quot;三、了空居士的日常工作开示&quot;">​</a></h2><blockquote><p><strong>&quot;跟你讲得最简单：与人为善，观察自己的念头。正确的给予肯定，错误的给予否定，解不开的诚心请教别人。&quot;</strong></p></blockquote><p>— 答疑专辑</p><blockquote><p><strong>&quot;以无我、无人、无众生、无寿者，修一切善法。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经23分-净心行善">金刚经23分-净心行善</a></p><blockquote><p><strong>&quot;了解就多帮助，不了解就少帮助，这是最客观的。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a></p><hr><h2 id="四、常见场景对治" tabindex="-1">四、常见场景对治 <a class="header-anchor" href="#四、常见场景对治" aria-label="Permalink to &quot;四、常见场景对治&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>原文依据</th></tr></thead><tbody><tr><td>领导批评你</td><td>&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot; — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></td></tr><tr><td>同事甩锅给你</td><td>不生怨恨，解决问题优先。理智是操作手柄 — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></td></tr><tr><td>重复枯燥的工作</td><td>每一件小事做到细致圆满 — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-细致圆满">金刚经1分-细致圆满</a></td></tr><tr><td>升职不如意</td><td>&quot;因上精进，果上随缘&quot; — <a href="/liaokongjushi-wisdom/60-原文段落/道德经14章-因上精进果上随缘">道德经14章-因上精进果上随缘</a></td></tr><tr><td>遇到苛刻客户</td><td>换位思维，用整体观理解他的需求 — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-整体观是非对错">金刚经7分-整体观是非对错</a></td></tr></tbody></table><hr><h2 id="五、常见误解" tabindex="-1">五、常见误解 <a class="header-anchor" href="#五、常见误解" aria-label="Permalink to &quot;五、常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>修行要专门时间，工作忙修不了</td><td>&quot;认真工作也是禅定&quot;</td><td>修行即生活（20090111b）</td></tr><tr><td>工作中不能念佛修行</td><td>&quot;行住坐卧，绵绵若存&quot;——任何时候都可轻轻返观</td><td><a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></td></tr><tr><td>工作场合不能谈修行</td><td>&quot;和光同尘&quot;——不标榜自己在修行，做好事不需让人知道</td><td><a href="/liaokongjushi-wisdom/60-原文段落/道德经4章-和光同尘">道德经4章-和光同尘</a></td></tr></tbody></table><hr><h2 id="六、推荐模型" tabindex="-1">六、推荐模型 <a class="header-anchor" href="#六、推荐模型" aria-label="Permalink to &quot;六、推荐模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-历境炼心">历境炼心</a> — 工作中的每一件事都是炼心机会</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">自然务实</a> — 化繁为简，做就是了</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">圆融中和</a> — 整体观处世，不偏不倚</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">对境不住</a> — 不被工作中的&quot;相&quot;带跑</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-处世">dict-处世</a> — 工作是处世的重要场景</li><li><a href="/liaokongjushi-wisdom/meta-整体观">meta-整体观</a> — 用整体观处理工作中的人际关系</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（删除无出处引文，全部方法/引文添加原文段落链接，新增常见误解表） 来源：修行即生活（20090111b）、答疑专辑、金刚经</p></blockquote>',47)])])}const b=o(d,[["render",i]]);export{p as __pageData,b as default};
